		LmdbNativeStrategyProposal<AutoCloseable> original = new LmdbNativeStrategyProposal<>(() -> value,
				1D, "nestedLoop");
		LmdbNativeStrategyProposal<String> mapped = original.map(ignored -> {
			throw failure;
		}, "nestedLoop(fullValue)");
