	@Test
	public void probeBufferClosesTheInputWhenRowProductionFails() {
		AtomicBoolean closed = new AtomicBoolean();
		RuntimeException failure = new RuntimeException("injected row failure");
		RowState row = new RowState(null, NativeSlotLayout.empty(), EmptyBindingSet.getInstance());
		NativeUnorderedInput input = NativeUnorderedInput.rows(row, new RowCursor() {
			@Override
			public boolean next() {
				throw failure;
			}

			@Override
			public void close() {
				closed.set(true);
			}
		});

		assertThatThrownBy(() -> new NativeProbeBufferHarness().drainBounded(input, null, 8))
				.isSameAs(failure);
		assertThat(closed).as("the failing probe still owns the input's native read lease").isTrue();
		assertThat(input.closed).isTrue();
	}

	/**
	 * These cases pin the ranking RULE, so they must not inherit what other queries in the same JVM taught the runtime
	 * calibrator — with learned factors in play, a measured speed difference legitimately overrules a specialization
	 * tie-break, which would make these assertions depend on test execution order.
	 */
	@org.junit.jupiter.api.BeforeEach
	public void isolateFromLearnedCalibration() {
		LmdbNativeCostCalibration.reset();
		System.setProperty(LmdbNativeAdaptiveCostModel.RECORD_PROPERTY, "true");
	}

	@org.junit.jupiter.api.AfterEach
	public void clearCalibrationState() {
		LmdbNativeCostCalibration.reset();
		System.clearProperty(LmdbNativeCostCalibration.ENABLED_PROPERTY);
		System.clearProperty(LmdbNativeCostCalibration.EXPLORATION_PROPERTY);
		System.clearProperty(LmdbNativeAdaptiveCostModel.RECORD_PROPERTY);
		System.clearProperty(LmdbNativeStrategyProposal.PARALLEL_STARTUP_COST_PROPERTY);
		System.clearProperty(LmdbNativeParallelPipelines.MIN_WORK_ESTIMATE_PROPERTY);
		System.clearProperty(LmdbNativeAdaptiveCostModel.ENABLED_PROPERTY);
	}

	private static void measure(String tag, double nanosPerUnit, int times) {
		for (int i = 0; i < times; i++) {
			LmdbNativeCostCalibration.record(tag, 10_000d, (long) (nanosPerUnit * 10_000d));
		}
	}

	private static LmdbNativeStrategyProposal<String> proposal(String tag, LmdbNativeWork work) {
		return new LmdbNativeStrategyProposal<>(() -> tag, work, tag, () -> {
		});
	}

	private static LmdbNativeStrategyProposal<String> proposal(String tag, double cost) {
		return proposal(tag, LmdbNativeWork.exact(cost));
	}

	private static String winner(List<LmdbNativeStrategyProposal<String>> candidates) {
		int index = LmdbNativeStrategyArbiter.rank(candidates);
		return index < 0 ? null : candidates.get(index).tag;
	}

	private static String adaptiveWinner(List<LmdbNativeStrategyProposal<String>> candidates) {
		LmdbNativeAdaptiveCostModel model = new LmdbNativeAdaptiveCostModel(new LmdbNativeMachineCostModel(),
				new LmdbNativeStoreCostModel(), LmdbNativeAdaptiveCostModel.Configuration.system());
		int index = LmdbNativeStrategyArbiter.rankAdaptive(candidates, -1D, model);
		return index < 0 ? null : candidates.get(index).tag;
	}

