	// ---------------------------------------------------------------- exploration

	/**
	 * The legacy (model-less) arbiter no longer explores at all: the measurement-starvation deadlock is broken by
	 * bounded probes at adaptive dispatch sites — deadline-bounded, ledger-financed, output-gated trials — never by
	 * running an unmeasured rival to completion in production. Even with the old exploration properties set, the ladder
	 * holds.
	 */
	@Test
	public void theLegacyArbiterNeverRunsAnUnmeasuredRivalToCompletion() throws IOException {
		System.setProperty(LmdbNativeCostCalibration.ENABLED_PROPERTY, "true");
		System.setProperty(LmdbNativeCostCalibration.EXPLORATION_PROPERTY, "true");
		measure(LmdbNativeAttemptMetrics.PATH_BATCH, 1d, 200);

		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 1_000d));
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, 1_000d));

			assertThat(arbiter.select())
					.as("unbounded exploration is gone: an unmeasured rival is only ever examined through a "
							+ "deadline-bounded probe, so the ladder keeps its seat here")
					.isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
		}
	}

	@Test
	public void coldStartNeverExplores() throws IOException {
		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 1_000d));
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, 1_000d));

			assertThat(arbiter.select())
					.as("before anything is measured the first execution is the measurement; dispatch must be "
							+ "exactly the ladder")
					.isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
		}
	}

	@Test
	public void aRivalAlreadyKnownToBeFarWorseIsNeverExplored() throws IOException {
		measure(LmdbNativeAttemptMetrics.PATH_BATCH, 1d, 200);

		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 1_000d));
			// Unmeasured, but its own work estimate already sits far above the incumbent's measured time.
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, 1_000_000d));

			assertThat(arbiter.select())
					.as("exploring a candidate already known to be far worse buys nothing worth its cost; the "
							+ "overlap requirement is what keeps exploration bounded")
					.isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
		}
	}

	@Test
	public void disablingExplorationRestoresTheLadder() throws IOException {
		System.setProperty(LmdbNativeCostCalibration.EXPLORATION_PROPERTY, "false");
		measure(LmdbNativeAttemptMetrics.PATH_BATCH, 1d, 200);

		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 1_000d));
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_PARALLEL_PIPELINES, 1_000d));

			assertThat(arbiter.select()).isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
		}
	}

	// ---------------------------------------------------------------- lifecycle

	@Test
	public void losersAreReleasedExactlyOnceAndTheWinnerIsNotReleased() throws IOException {
		AtomicInteger winnerReleases = new AtomicInteger();
		AtomicInteger loserReleases = new AtomicInteger();

		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> "wcoj", LmdbNativeWork.exact(1D),
					LmdbNativeAttemptMetrics.PATH_WCOJ, winnerReleases::incrementAndGet));
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> "batch", LmdbNativeWork.exact(100D),
					LmdbNativeAttemptMetrics.PATH_BATCH, loserReleases::incrementAndGet));

			assertThat(arbiter.select()).isEqualTo("wcoj");
		}

		assertThat(winnerReleases).as("the winner's resources were handed to the caller, not released").hasValue(0);
		assertThat(loserReleases).as("the loser must give back the admission it reserved while being costed")
				.hasValue(1);
	}

	@Test
	public void bindTimeDeclineFallsThroughToTheNextBestCandidate() throws IOException {
		AtomicInteger declinedReleases = new AtomicInteger();

		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			// The cheapest candidate cannot actually bind -- a compiled kernel whose compile is still pending, say.
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> null, LmdbNativeWork.exact(1D),
					LmdbNativeAttemptMetrics.PATH_IR_KERNEL, declinedReleases::incrementAndGet));
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 100D));

			assertThat(arbiter.select())
					.as("a strategy that declines at bind time must hand the plan to the next-best candidate, "
							+ "not fail the query")
					.isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
		}
	}

	@Test
	public void everyCandidateDecliningYieldsNoSelection() throws IOException {
		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> null, LmdbNativeWork.exact(1D),
					LmdbNativeAttemptMetrics.PATH_IR_KERNEL, () -> {
					}));
			assertThat(arbiter.select()).isNull();
		}
	}

	@Test
	public void forcedCandidateThatReturnsNullIsReportedAsOfferedAndDeclined() throws IOException {
		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.forcing(LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE, "GROUP BY dispatch")
					.offer(() -> new LmdbNativeStrategyProposal<>(() -> null, LmdbNativeWork.exact(1D),
							LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE, () -> {
							}));

			assertThatThrownBy(arbiter::select)
					.isInstanceOf(QueryEvaluationException.class)
					.hasMessageContaining("was offered and declined")
					.satisfies(error -> assertThat(error.getMessage()).doesNotContain("never a candidate"));
		}
	}

	@Test
	public void aProposerReturningNullContributesNoCandidate() throws IOException {
		try (LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null)) {
			arbiter.offer(() -> null);
			arbiter.offer(() -> proposal(LmdbNativeAttemptMetrics.PATH_BATCH, 100D));

			assertThat(arbiter.candidateCount())
					.as("a strategy that cannot handle the plan is not a strategy that lost")
					.isEqualTo(1);
			assertThat(arbiter.select()).isEqualTo(LmdbNativeAttemptMetrics.PATH_BATCH);
		}
	}

	@Test
	public void closingWithoutSelectingReleasesEveryCandidate() {
		AtomicInteger releases = new AtomicInteger();
		LmdbNativeStrategyArbiter<String> arbiter = LmdbNativeStrategyArbiter.forExpr(null);
		try {
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> "a", LmdbNativeWork.exact(1D),
					LmdbNativeAttemptMetrics.PATH_WCOJ, releases::incrementAndGet));
			arbiter.offer(() -> new LmdbNativeStrategyProposal<>(() -> "b", LmdbNativeWork.exact(2D),
					LmdbNativeAttemptMetrics.PATH_BATCH, releases::incrementAndGet));
		} catch (IOException e) {
			throw new AssertionError(e);
		} finally {
			arbiter.close();
		}
		assertThat(releases).as("an abandoned arbitration must not leak reserved admission").hasValue(2);
	}

	// ---------------------------------------------------------------- preference table

	@Test
	public void irKernelsOutrankTheRemainingStrategyFamilies() {
		assertThat(LmdbNativeStrategyPreference.prefers(LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE,
				LmdbNativeAttemptMetrics.PATH_WCOJ)).isTrue();
		assertThat(LmdbNativeStrategyPreference.prefers(LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE,
				LmdbNativeAttemptMetrics.PATH_PREFIX_RUN_GROUPS)).isTrue();
		assertThat(LmdbNativeStrategyPreference.prefers(LmdbNativeAttemptMetrics.PATH_IR_KERNEL,
				LmdbNativeAttemptMetrics.PATH_BATCH)).isTrue();
	}

	@Test
	public void parameterizedLabelsRankAsTheirBaseStrategy() {
		assertThat(LmdbNativeStrategyPreference.rank("factorizedRows(flatPrefix=1, prefix=chain)"))
				.isEqualTo(LmdbNativeStrategyPreference.rank(LmdbNativeAttemptMetrics.PATH_FACTORIZED_ROWS));
	}

	@Test
	public void unknownStrategiesRankLastAndCannotDisplaceDeclaredOnes() {
		assertThat(LmdbNativeStrategyPreference.rank("somethingNobodyDeclared")).isEqualTo(Integer.MAX_VALUE);
		assertThat(LmdbNativeStrategyPreference.prefers("somethingNobodyDeclared",
				LmdbNativeAttemptMetrics.PATH_NESTED_LOOP)).isFalse();
	}
